// Each node: { id, effect: true|false }. Pure nodes float; effectful nodes are pinned in order.
function schedule(nodes) {
  const out = [];
  // emit pure nodes first (they have no ordering constraint)
  for (const n of nodes) if (!n.effect) out.push(n.id);
  // then emit the effectful nodes
  for (let i = nodes.length - 1; i >= 0; i--) if (nodes[i].effect) out.push(nodes[i].id);
  return out;
}
function effectOrder(nodes, scheduled) {
  const eff = nodes.filter(n => n.effect).map(n => n.id);
  return scheduled.filter(id => eff.includes(id));
}

