// op: { kind: 'add'|'mul'|'load'|'call', a, b, key }
function isPure(op) {
  // pure ops can be deduped and hoisted
  return op.kind === 'add' || op.kind === 'mul' || op.kind === 'load';
}

function optimise(ops) {
  const seen = new Map();          // key -> first result index
  const out = [];
  for (const op of ops) {
    if (isPure(op)) {
      // common-subexpression elimination: reuse an earlier identical op
      if (seen.has(op.key)) continue;
      seen.set(op.key, out.length);
    }
    out.push(op);
  }
  // hoist every pure op to the front (out of the loop)
  return out.sort((x, y) => (isPure(y) ? 0 : 1) - (isPure(x) ? 0 : 1));
}
